css:
.plugin-kanban-overlay { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.55); z-index: 9000; display: flex; align-items: center; justify-content: center; }
.plugin-kanban-panel { background: var(--surface, #fff); color: var(--text, #111); border: 1px solid var(--border, #ccc); border-radius: 8px; width: min(960px, 92vw); max-height: 85vh; overflow: auto; padding: 16px; }
.plugin-kanban-title { font-weight: 700; font-size: 18px; margin-bottom: 8px; }
.plugin-kanban-close { float: right; }
.plugin-kanban-columns { display: flex; gap: 12px; align-items: flex-start; }
.plugin-kanban-column { flex: 1; min-width: 0; background: var(--bg, #fafafa); border: 1px solid var(--border, #ccc); border-radius: 6px; padding: 8px; }
.plugin-kanban-column-title { font-weight: 700; font-size: 12px; letter-spacing: 0.08em; margin-bottom: 8px; color: var(--text-muted, #666); }
.plugin-kanban-card { border: 1px solid var(--border, #ccc); border-radius: 4px; padding: 8px; margin-bottom: 8px; background: var(--surface, #fff); }
.plugin-kanban-move { display: block; margin-top: 6px; font-size: 11px; }

js:
var STATUSES = ['todo', 'doing', 'done'];

var openBtn = document.createElement('button');
openBtn.className = 'btn plugin-kanban-btn';
openBtn.textContent = 'Board';
ctx.api.ui.inject('.header', openBtn, 'append');

var overlay = document.createElement('div');
overlay.className = 'plugin-kanban-overlay';
overlay.style.display = 'none';
ctx.api.ui.inject('body', overlay, 'append');

function statusOf(card) {
  var tags = card.tags || [];
  for (var i = 0; i < STATUSES.length; i++) {
    if (tags.indexOf(STATUSES[i]) !== -1) return STATUSES[i];
  }
  return 'todo';
}

function moveCard(card, status) {
  var tags = (card.tags || []).filter(function(t) { return STATUSES.indexOf(t) === -1; });
  tags.push(status);
  ctx.api.data.setTags(card.id, tags);
  renderBoard();
}

function renderBoard() {
  overlay.innerHTML = '';
  var panel = document.createElement('div');
  panel.className = 'plugin-kanban-panel';

  var closeBtn = document.createElement('button');
  closeBtn.className = 'btn plugin-kanban-close';
  closeBtn.textContent = 'Close';
  closeBtn.onclick = function() { overlay.style.display = 'none'; };
  panel.appendChild(closeBtn);

  var title = document.createElement('div');
  title.className = 'plugin-kanban-title';
  title.textContent = 'Kanban Board';
  panel.appendChild(title);

  var columns = document.createElement('div');
  columns.className = 'plugin-kanban-columns';
  var cards = ctx.api.data.listCards();

  STATUSES.forEach(function(status) {
    var col = document.createElement('div');
    col.className = 'plugin-kanban-column';
    var head = document.createElement('div');
    head.className = 'plugin-kanban-column-title';
    head.textContent = status.toUpperCase();
    col.appendChild(head);

    cards.filter(function(c) { return statusOf(c) === status; }).forEach(function(card) {
      var item = document.createElement('div');
      item.className = 'plugin-kanban-card';
      item.textContent = card.title || '(Untitled)';
      var idx = STATUSES.indexOf(status);
      if (idx < STATUSES.length - 1) {
        var fwd = document.createElement('button');
        fwd.className = 'btn plugin-kanban-move';
        fwd.textContent = 'Move to ' + STATUSES[idx + 1];
        fwd.onclick = function() { moveCard(card, STATUSES[idx + 1]); };
        item.appendChild(fwd);
      }
      col.appendChild(item);
    });

    columns.appendChild(col);
  });

  panel.appendChild(columns);
  overlay.appendChild(panel);
}

openBtn.onclick = function() { renderBoard(); overlay.style.display = 'flex'; };
overlay.onclick = function(e) { if (e.target === overlay) overlay.style.display = 'none'; };

ctx.logger.info('Kanban board ready');
